        { "I crossed into {zone}." },
        { "{zone}. The living there gave me a wide berth.", tags = { "aside" } },
      },
    },
  },
  scenery = {
    ["Auberdine"] = { type = "town", faction = "alliance", home = {  },
      { "I came into Auberdine through the grey sea mist, with the harbour piers stretching out before me. Boats came and went, but the people on shore wore the look of those who had been waiting too long.", tags = { "!foe" } },
      { "The ships in Auberdine's harbour told me whose shore this was before I saw the guards. I could admire the shelter of those piers without expecting to be welcome beneath them.", tags = { "foe" } },
    },
    ["Blackfathom Deeps"] = { type = "dungeon", faction = "neutral", home = {  },
      { "I entered Blackfathom Deeps with the sea still reaching into the old temple's halls. Black water hid the lower steps, and every sound travelled farther than I wanted it to; I found myself listening before I moved." },
    },
    ["Brill"] = { type = "town", faction = "horde", home = { ["Scourge"] = true },
      { "The crooked roofs of Brill looked almost companionable after the tombs. Around the Gallows' End Tavern, my people went about their business as though a town could carry on by stubbornness alone, and for a while I felt part of it.", tags = { "home" } },
      { "I reached Brill beneath crooked roofs and the sign of the Gallows' End Tavern. The townsfolk were dead, yet they had shops to tend and errands to run; I was less prepared for that than for the graves.", tags = { "!home" } },
    },
    ["Darkshore"] = { type = "zone", faction = "alliance", home = {  },
      { "I followed Darkshore's grey coast with the mist coming off the sea and old elven stones half buried in the sand. Even the trees seemed worn by the weather, and I found myself looking for lights along the shore.", tags = { "!night" } },
      { "I could scarcely tell the sea from the sky when I came into Darkshore after dark. The moon was a pale blur behind the mist, and I listened to the surf to keep my bearings.", tags = { "night" } },
    },
    ["Darnassus"] = { type = "zone", faction = "alliance", home = { ["NightElf"] = true },
      { "I came into Darnassus past white stone and still pools, and slowed without meaning to. Near the Temple of the Moon, I felt the familiar hush settle around me; there were places where my people still knew how to be quiet.", tags = { "home" } },
      { "I lowered my voice as I entered Darnassus, though no one had asked me to. The pale stone and quiet pools seemed to belong to a different pace of life, high above the world I had travelled through.", tags = { "ally" } },
      { "I entered Darnassus with its pale stone and still water all around me. The quiet might have been beautiful to someone welcome there; to me, it made every footstep sound too loud.", tags = { "foe" } },
    },
    ["Dolanaar"] = { type = "town", faction = "alliance", home = { ["NightElf"] = true },
      { "I came to Dolanaar with the smell of rain in the air. The houses gathered around the moonwell, and the sentinels watched the road with a patience that let me lower my guard a little.", tags = { "home" } },
      { "The blue glow of Dolanaar's moonwell drew my eye before the houses did. Beneath the wood and trailing vines, even the voices were quiet, and I caught myself speaking softly too.", tags = { "!home" } },
    },
    ["Dun Morogh"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true, ["Gnome"] = true },
      { "The cold of Dun Morogh caught in my throat while snow weighed down the pines around me. Above them stood the mountain that held Ironforge, and its familiar shape made the country feel less empty.", tags = { "home", "!night" } },
      { "Under the stars, the snow of Dun Morogh had turned blue and the village lamps looked warmer for it. I could still pick out the mountains against the sky; they were familiar company in the dark.", tags = { "home", "night" } },
      { "I felt Dun Morogh in my fingers before I had much chance to look at it. Deep snow lay against the rock, and the gate of Ironforge disappeared into the mountain as though the dwarves had persuaded the stone to make room.", tags = { "ally" } },
      { "I came into Dun Morogh with snow underfoot and the dwarves' mountain ahead of me. Every glimpse of Ironforge reminded me how many of them could be hidden behind that stone.", tags = { "foe" } },
    },
    ["Durotar"] = { type = "zone", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "Red dust rose around my feet in Durotar, and the heat seemed to come from the ground as well as the sky. This was the land we had claimed for ourselves; I wanted to learn how to belong to it.", tags = { "home", "!night" } },
      { "The red earth of Durotar had faded to grey by the time the heat began to leave the stones. Somewhere beyond the dark hills, Orgrimmar's drums carried on, a sound I could follow without seeing its walls.", tags = { "home", "night" } },
      { "I came into Durotar beneath a sun that left little room for comfort. Red hills folded around the road, and the great gate of Orgrimmar stood ahead in the canyon; I began to understand the people who had chosen to stay.", tags = { "ally" } },
      { "The hot wind drove Durotar's red dust against me as I looked toward the orcs' country. I had crossed into the heart of the Horde, and the ridges no longer looked empty.", tags = { "foe" } },
    },
    ["Gnomeregan"] = { type = "dungeon", faction = "alliance", home = { ["Gnome"] = true },
      { "I had imagined returning to Gnomeregan so often that the sight of it should have been familiar. Instead there were troggs in our halls and that poisonous glow on everything, and I could not stop looking for faces I might still know.", tags = { "home" } },
      { "I entered Gnomeregan to the sound of machines still working in halls their makers had lost. The green light lay over the metal like a sickness, and I wondered how long those wheels would turn with no one left to stop them.", tags = { "!home" } },
    },
    ["Ironforge"] = { type = "zone", faction = "alliance", home = { ["Dwarf"] = true },
      { "The heat of the Great Forge reached my face as I entered Ironforge, followed by the ring of hammers. I stood a moment above the channels of molten iron and let the noise of my people's work fill the space the road had left.", tags = { "home" } },
      { "I came into Ironforge out of the mountain cold and felt the Great Forge's heat before I reached it. Hammers rang through the halls, and after the open country the sheer business of the place was almost comforting.", tags = { "ally" } },
      { "The mountain closed around me when I entered Ironforge, and the hammering seemed to come from every hall. Its warmth offered no comfort; there were guards enough here to make me conscious of every turn.", tags = { "foe" } },
    },
    ["Kharanos"] = { type = "town", faction = "alliance", home = { ["Dwarf"] = true, ["Gnome"] = true },
      { "I smelled the Thunderbrew Distillery before I had properly reached Kharanos. Smoke rose above the houses, where dwarves and gnomes crowded together against the cold, and I felt my shoulders ease at the sight.", tags = { "home" } },
      { "The smell of brewing reached me on the road into Kharanos. Among the sturdy houses I saw gnomes as well as dwarves, and thought of how far a lost home could follow its people.", tags = { "ally" } },
      { "Smoke hung over Kharanos, and the smell of ale carried well beyond the houses. It might have promised a welcome to someone else; I found myself counting the dwarves instead.", tags = { "foe" } },
    },
    ["Loch Modan"] = { type = "zone", faction = "alliance", home = {  },
      { "The blue water of Loch Modan opened before me between red hills, with the Stonewrought Dam closing off its far end. I had known that dwarves built on a grand scale, but the weight of all that water made me pause.", tags = { "!night" } },
      { "I came into Loch Modan with the lake black and still beneath the hills. The dam made a darker line against the sky, while the little lights of Thelsamar drew my eye back to the shore.", tags = { "night" } },
      { "I looked across Loch Modan toward the dwarves' great dam. Their guards watched the roads beside the water, and I paid as much attention to them as to the view.", tags = { "foe" } },
    },
    ["Orgrimmar"] = { type = "zone", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "I came beneath Orgrimmar's spiked walls with the drums sounding through the canyon. Here was a city our people had built for themselves, and the sight of Grommash Hold gave weight to words I had heard about the Horde all my life.", tags = { "home" } },
      { "I entered Orgrimmar between red stone and iron spikes, with smoke drifting above the canyon. The drums carried through the streets, and I felt the city's pride in the way its people moved through it.", tags = { "ally" } },
      { "Orgrimmar's walls looked formidable enough from outside. Beneath them, with drums echoing off the red stone, I became sharply aware of how far I was from anyone who would call me a friend.", tags = { "foe" } },
    },
    ["Ragefire Chasm"] = { type = "dungeon", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "I went down into Ragefire Chasm beneath our own city, where the heat pressed against my face and fire ran through the stone. The thought of the Burning Blade hiding so close to Orgrimmar troubled me more than the darkness.", tags = { "home" } },
      { "The air grew hotter as I entered Ragefire Chasm beneath Orgrimmar. Magma lit the stone from below, and I had to remind myself to watch the ground rather than stare at the fire.", tags = { "!home" } },
    },
    ["Razor Hill"] = { type = "town", faction = "horde", home = { ["Orc"] = true, ["Troll"] = true },
      { "At Razor Hill I heard the forge and saw the drilling before I had finished taking in the town. Beyond the barracks lay the coast and the Kul Tiras ships, and I understood why no one here seemed quite at rest.", tags = { "home" } },
      { "I reached Razor Hill among barracks and watchtowers, with the coast somewhere beyond them. There were weapons everywhere I looked, and I could not mistake this for a town that had forgotten its enemies.", tags = { "!home" } },
    },
    ["Shadowfang Keep"] = { type = "dungeon", faction = "neutral", home = {  },
      { "I climbed into Shadowfang Keep above Pyrewood with cold stone enclosing me and howls carrying through the halls. Arugal's name belonged to this place, but it was the sounds behind the walls that kept my attention." },
    },
    ["Silverpine Forest"] = { type = "zone", faction = "horde", home = {  },
      { "Cold rain followed me into Silverpine Forest, darkening the pines and blurring the grey lake. Across the water I could make out Dalaran's purple dome, but the howling in the hills kept drawing my attention nearer.", tags = { "!night" } },
      { "I came into Silverpine after dark with rain in the trees and howls somewhere beyond them. The pines made a black wall around the road, and I had little wish to learn what lay on the other side.", tags = { "night" } },
    },
    ["Teldrassil"] = { type = "zone", faction = "alliance", home = { ["NightElf"] = true },
      { "I looked up through Teldrassil's leaves and tried to hold in mind that this whole country rested on branches. Wisps drifted over the moss as though nothing were unusual; I was still learning to feel that sure of our new home.", tags = { "home", "!night" } },
      { "Moonlight silvered the leaves around me in Teldrassil, and the owls called somewhere overhead. I listened to them between my own footfalls, unwilling to hurry through so much quiet.", tags = { "home", "night" } },
      { "I walked into Teldrassil's violet light knowing that the forest beneath my feet was growing on a tree. The thought returned whenever I looked between the great leaves, and for a while I paid more attention to the ground than the sentinels.", tags = { "ally" } },
      { "I entered Teldrassil beneath leaves that softened every sound. I could admire the beauty of the night elves' home while feeling certain that someone had noticed me already.", tags = { "foe" } },
    },
    ["The Barrens"] = { type = "zone", faction = "horde", home = {  },
      { "I came into the Barrens with yellow grass stretching farther than I could see. Zhevra moved between the thorn trees, and the heat settled over everything; the distance ahead was harder to judge than it had looked on a map.", tags = { "!night" } },
      { "The grass of the Barrens shone silver when I reached it after dark. Above me the sky seemed enormous, but the distant beat of centaur drums kept my thoughts on the country beneath it.", tags = { "night" } },
    },
    ["The Crossroads"] = { type = "town", faction = "horde", home = {  },
      { "The palisade of the Crossroads appeared where the roads met in the open grassland. After so much distance, the sight of people gathered in one place was a relief, even before I knew what work they might have for me.", tags = { "!foe" } },
      { "I came upon the Crossroads where the roads of the Barrens met. The Horde's palisade promised shelter to its own travellers; to me it was another reason to look carefully before moving on.", tags = { "foe" } },
    },
    ["The Sepulcher"] = { type = "town", faction = "horde", home = { ["Scourge"] = true },
      { "I reached the Sepulcher among the tombs, with bats overhead and our guards at the gate. We had made an outpost out of a burial place, which struck me as a fair use of what the world had left us.", tags = { "home" } },
      { "I came to the Sepulcher through a hillside of tombs. The guards stood so still that I watched for a blink before remembering who lived here.", tags = { "!home" } },
    },
    ["Thelsamar"] = { type = "town", faction = "alliance", home = {  },
      { "I came into Thelsamar with the loch nearby and the Stoutlager Inn among the houses. After the open hills, I found myself thinking rather more about its ale and blood sausages than about how far I had travelled.", tags = { "!foe" } },
      { "The houses of Thelsamar gathered beside the loch, with an inn that looked comfortable enough. I was on the Alliance's shore, though, and its windows offered more opportunity to be seen than to rest.", tags = { "foe" } },
    },
    ["Tirisfal Glades"] = { type = "zone", faction = "horde", home = { ["Scourge"] = true },
      { "I looked out over the grey grass of Tirisfal Glades beneath a sky that never seemed to clear. The dead trees stood where the plague had left them, and I recognised something of myself in a country obliged to go on like this.", tags = { "home", "!night" } },
      { "The crypts of Tirisfal were dark behind me, and crows called toward the broken walls of Lordaeron. Night had changed little in the landscape, but I felt less conspicuous beneath it.", tags = { "home", "night" } },
      { "I came into Tirisfal Glades through grey fields and dead trees, with crows gathering toward the broken walls of Lordaeron. It was difficult to look at the country without wondering what its people remembered of it.", tags = { "ally" } },
      { "I entered Tirisfal Glades beneath a grey sky, with dead trees stretching toward the ruins of Lordaeron. Knowing that the Forsaken walked here made the stillness harder to trust.", tags = { "foe" } },
    },
    ["Undercity"] = { type = "zone", faction = "horde", home = { ["Scourge"] = true },
      { "I descended into the Undercity beneath Lordaeron's ruins and found our city going about its business. Green liquid filled the canals and the Apothecarium bubbled nearby; among so much that had survived badly, we had found a way to remain.", tags = { "home" } },
      { "I went below the ruins of Lordaeron into the Undercity, where green sludge ran through the stone canals. The smell reached me before I had found my way through the passages, and stayed with me while I tried to.", tags = { "ally" } },
      { "I descended beneath Lordaeron's ruins into the Undercity. Down here the Forsaken had made a home, and each turn into another passage made the way back to daylight feel less certain.", tags = { "foe" } },
    },
    ["Wailing Caverns"] = { type = "dungeon", faction = "neutral", home = {  },
      { "I entered the Wailing Caverns with a moaning wind moving through the stone and green water below the roots. I had heard what became of the druids who came to heal this land; down here, I kept listening for something that sounded human." },
    },
  },
}
